      researchCost: { sampleSize: costSummary.requestCount, summary: costSummary },
      evidenceQuality: { sampleSize: evidenceRows.reduce((sum, row) => sum + number4(row.count), 0), rows: evidenceRows },
      factExtractionQuality: { sampleSize: factRows.reduce((sum, row) => sum + number4(row.count), 0), rows: factRows },
